// BizCard ortak dogrulama: "Karti Kaydet" ve "Toplanti Talep Et" akislari ayni kurallari kullanir.
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;
const TIME_REGEX = /^([01]\d|2[0-3]):[0-5]\d$/;
const VALID_EVENTS = ["card.save", "meeting.request"];
const VALID_CARD_IDS = ["sercan-balli"];
const item = $input.first().json;
const errors = [];
if (!VALID_EVENTS.includes(item.event)) { errors.push("Gecersiz olay turu: " + item.event); }
if (!VALID_CARD_IDS.includes(item.cardId)) { errors.push("Bilinmeyen kart ID: " + item.cardId); }
if (!item.email || !EMAIL_REGEX.test(item.email)) { errors.push("Gecersiz e-posta formati: " + item.email); }
if (!item.timestamp || isNaN(Date.parse(item.timestamp))) { errors.push("Gecersiz zaman damgasi: " + item.timestamp); }
if (item.event === "meeting.request") {
  if (!DATE_REGEX.test(item.preferredDate || "")) { errors.push("Gecersiz toplanti tarihi: " + item.preferredDate); }
  if (!TIME_REGEX.test(item.preferredTime || "")) { errors.push("Gecersiz toplanti saati: " + item.preferredTime); }
}
return [{ json: { valid: errors.length === 0, reason: errors.join(" | ") } }];

// Dongu bittiginde tum kayitlar burada toplanir; olay turune gore gruplanir.
const today = $now.toFormat("yyyy-MM-dd");
const groups = {};
for (const item of $input.all()) {
  const { tur, adSoyad } = item.json;
  if (!groups[tur]) groups[tur] = { sayi: 0, kisiler: [] };
  groups[tur].sayi += 1;
  groups[tur].kisiler.push(adSoyad);
}
return Object.keys(groups).map((tur) => ({ json: { ozetTarihi: today, tur, kayitSayisi: groups[tur].sayi, kisiler: groups[tur].kisiler.join(", ") } }));

// n8n API'den gelen execution'lari bu haftaya (Pazartesi 00:00'dan itibaren) filtreleyip olay turune gore sayar.
const weekStart = $now.startOf("week");
const sonuc = { haftaBaslangici: weekStart.toFormat("yyyy-MM-dd"), buHaftaToplamIstek: 0, kartKaydi: 0, toplantiTalebi: 0, basarisiz: 0, tumZamanlarToplantiTalebi: 0 };
for (const item of $input.all()) {
  const j = item.json;
  const raw = JSON.stringify(j.data || {});
  const toplanti = raw.includes("meeting.request");
  const kart = raw.includes("card.save");
  if (toplanti) sonuc.tumZamanlarToplantiTalebi++;
  if (DateTime.fromISO(j.startedAt) < weekStart) continue;
  sonuc.buHaftaToplamIstek++;
  if (toplanti) sonuc.toplantiTalebi++;
  else if (kart) sonuc.kartKaydi++;
  if (j.status === "error") sonuc.basarisiz++;
}
return [{ json: sonuc }];

// Form tek bir item uretir; uc PDF'i ayri item'lara boler ve her birine kendi metadata'sini ekler.
const item = $input.first();
const keys = Object.keys(item.binary || {});
if (keys.length < 3) {
  throw new Error("Uc PDF dosyasi yuklenmelidir: profil rehberi, toplanti politikasi ve kurumsal rehber.");
}
const dokumanlar = [
  {
    dokuman_turu: "profil_hizmetler",
    dokuman_versiyonu: item.json["Profil Rehberi Versiyonu"],
    meta_title: "Profil, Hizmetler ve Kullanım Rehberi",
    meta_description: "Sercan BALLI'nın uzmanlık alanları, hizmetleri, çalışma şekli ve dijital kartvizit kullanımı.",
    meta_keywords: "profil, uzmanlık, hizmetler, çalışma şekli, kartvizit kullanımı, kartı kaydet, telefonuma ekle, QR kod",
  },
  {
    dokuman_turu: "toplanti_iletisim",
    dokuman_versiyonu: item.json["Toplanti Politikasi Versiyonu"],
    meta_title: "Toplantı ve İletişim Politikası",
    meta_description: "Toplantı talebi süreci, yanıt süresi, müsait saatler, toplantı süresi, iptal ve KVKK bilgileri.",
    meta_keywords: "toplantı, randevu, yanıt süresi, müsait saat, süre, iptal, KVKK",
  },
  {
    dokuman_turu: "kurumsal_bilgi",
    dokuman_versiyonu: item.json["Kurumsal Rehber Versiyonu"],
    meta_title: "Veri Endüstri Mühendislik A.Ş. Kurumsal Tanıtım ve Bilgi Rehberi",
    meta_description: "Şirket hakkında, faaliyet alanları, sektörler, çözüm paketleri, çalışma yöntemi, teknoloji, gizlilik, kariyer, iletişim ve sık sorulan sorular.",
    meta_keywords: "Veri Endüstri, şirket, kurumsal, faaliyet alanları, sektörler, çözüm paketleri, teknoloji, kariyer, staj, iletişim, SSS",
  },
];
return dokumanlar.map((d, i) => ({
  json: { ...d, kaynak_dokuman: item.binary[keys[i]].fileName, eklenme_tarihi: item.json.submittedAt },
  binary: { data: item.binary[keys[i]] },
}));

