// Sercan'in demo takvimi: hafta ici gunleri, yarindan itibaren 21 gun.
// Gunluk saatler: 10:00, 11:00, 13:00, 14:00, 15:00, 16:00. Carsamba 10:00-11:00 ve Cuma 15:00-16:00 dolu.
const q = String(query || "");
const dateMatch = q.match(/\d{4}-\d{2}-\d{2}/);
const timeMatch = q.match(/\b([01]?\d|2[0-3]):[0-5]\d\b/);
const reqDate = dateMatch ? dateMatch[0] : null;
const reqTime = timeMatch ? timeMatch[0].padStart(5, "0") : null;
const toMin = (t) => parseInt(t.slice(0, 2)) * 60 + parseInt(t.slice(3, 5));
const today = new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Istanbul" });
const base = new Date(today + "T00:00:00Z");
const days = [];
for (let i = 1; i <= 21; i++) {
  const d = new Date(base.getTime() + i * 86400000);
  const wd = d.getUTCDay();
  if (wd === 0 || wd === 6) continue;
  let slots = ["10:00", "11:00", "13:00", "14:00", "15:00", "16:00"];
  if (wd === 3) slots = slots.filter((s) => s !== "10:00" && s !== "11:00");
  if (wd === 5) slots = slots.filter((s) => s !== "15:00" && s !== "16:00");
  days.push({ tarih: d.toISOString().slice(0, 10), saatler: slots });
}
const reqDay = days.find((x) => x.tarih === reqDate);
if (reqDay && reqTime && reqDay.saatler.includes(reqTime)) {
  return JSON.stringify({ talepMusait: true, tarih: reqDate, saat: reqTime });
}
let alt = null;
if (reqDay && reqTime) {
  const sorted = [...reqDay.saatler].sort((a, b) => Math.abs(toMin(a) - toMin(reqTime)) - Math.abs(toMin(b) - toMin(reqTime)));
  alt = { tarih: reqDay.tarih, saat: sorted[0] };
}
if (!alt) {
  const next = days.find((x) => !reqDate || x.tarih > reqDate) || days[0];
  alt = { tarih: next.tarih, saat: next.saatler[0] };
}
return JSON.stringify({ talepMusait: false, talepTarih: reqDate, talepSaat: reqTime, alternatifTarih: alt.tarih, alternatifSaat: alt.saat });
